def format_amount(amount: Decimal, currency: str) -> str:
    q = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    # Group thousands for readability on invoices, e.g. "12,500.00 EUR".
    return f"{q:,} {currency}"


